// 2 days/week, ~45 min sessions, light intensity. Equipment: Resistance bands, Barbell, rack & bench, Dual adjustable pulley (cable), Dumbbells & bench, Kettlebells, Lat pulldown station, Pull-up bar.
# Week 1
// Estimated ~34 min
## Full Body A
// Brace, sit between your hips, knees track over toes.
Squat, Barbell / 2x10 / 20kg / 90s / progress: lp(2.5kg, 1, 0, 10%, 3, 0)
// Lower with control until elbows are just below the bench.
Bench Press, Dumbbell / 2x10 / 10kg / 90s / progress: dp(2kg, 10, 14)
// Hand on the bench, pull the dumbbell to your hip.
Bent Over One Arm Row, Dumbbell / 2x10 / 12kg / 90s / progress: dp(2kg, 10, 14)
// Pulley high, kneel with the rope, crunch ribs toward hips.
Cable Crunch, Cable / 2x12 / 15kg / 60s / warmup: none / progress: dp(2.5kg, 12, 16)
// Low pulley, elbows still, squeeze at the top.
Bicep Curl, Cable / 2x12 / 7.5kg / 60s / warmup: none / progress: dp(2.5kg, 12, 16)
// Low pulley across your body, raise out to the side.
Lateral Raise, Cable / 2x12 / 5kg / 60s / warmup: none / progress: dp(2.5kg, 12, 16)
// On a step if you can, slow on the way down.
Standing Calf Raise, Bodyweight / 2x8 / 0kg / 60s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}

// Estimated ~30 min
## Full Body B
// Soft knees, slide dumbbells down your thighs, hips back.
Romanian Deadlift, Dumbbell / 2x10 / 10kg / 90s / progress: dp(2kg, 10, 14)
// Squeeze glutes, press the bar up and move your head through.
Overhead Press, Barbell / 2x10 / 20kg / 90s / progress: lp(2.5kg, 1, 0, 10%, 3, 0)
// Palms facing you, pull chin over the bar. Do negatives if needed.
Chin Up, Bodyweight / 2x8 / 0kg / 60s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}
// Feet staggered, drop the back knee straight down.
Split Squat, Dumbbell / 2x12 / 6kg / 60s / warmup: none / progress: dp(2kg, 12, 16)
// Elbows pinned, push the bar/rope down to full lockout.
Triceps Pushdown, Cable / 2x12 / 15kg / 60s / warmup: none / progress: dp(2.5kg, 12, 16)
// Rope at face height, pull to your forehead, elbows high.
Standing Row Rear Delt With Rope, Cable / 2x12 / 7.5kg / 60s / warmup: none / progress: dp(2.5kg, 12, 16)
// Low back pressed into the floor, extend opposite arm and leg.
Dead Bug, Bodyweight / 2x8 / 0kg / 60s / warmup: none / progress: custom(maxReps: 15) {~
  if (completedReps >= reps && reps[ns] < state.maxReps) {
    reps += 1
  }
~}
